package au.monster.tracker;

import java.util.*;

public final class CatalogBackup {
    public static Catalog.Product product(Map<String,Object> m){Catalog.deleted(m);return new Catalog.Product(Purchases.str(m,"id"),Purchases.str(m,"name"),Purchases.num(m,"minimum"),Purchases.num(m,"target"),Purchases.num(m,"packSize"),Purchases.num(m,"packCost"),Purchases.str(m,"supplier"));}
    public static void validate(Map<String,Object> data,List<Ledger.Event> events){if(!data.keySet().equals(Ledger.set("products","barcodes","allocations","transfers")))Purchases.bad("Invalid catalogue backup fields.");Set<String> ids=new HashSet<>(),names=new HashSet<>(),displayNames=new HashSet<>();for(Object value:Purchases.list(data.get("products"))){var m=Purchases.map(value);var p=product(m);String display=Catalog.displayName(m,p.name());if(p.id().equals(Catalog.LEGACY)&&(Catalog.deleted(m)||!display.equals(p.name())))Purchases.bad("The unassigned historical flavour must keep its name and remain available.");if(!displayNames.add(display.toLowerCase(Locale.ROOT)))Purchases.bad("Duplicate flavour display name in backup.");if(!ids.add(p.id())||!names.add(p.name().toLowerCase(Locale.ROOT)))Purchases.bad("Duplicate flavour in backup.");}if(!ids.contains(Catalog.LEGACY))Purchases.bad("Unassigned historical flavour must be retained.");Set<String> codes=new HashSet<>();for(Object value:Purchases.list(data.get("barcodes"))){var m=Purchases.map(value);if(!codes.add(Catalog.barcode(Purchases.str(m,"code")))||!ids.contains(Purchases.str(m,"productId")))Purchases.bad("Invalid or duplicated barcode mapping.");}
        Map<String,Ledger.Event> source=new HashMap<>();for(var e:events)source.put(e.id(),e);Map<String,List<Catalog.Allocation>> allocations=new HashMap<>();for(Object value:Purchases.list(data.get("allocations"))){var m=Purchases.map(value);String id=Purchases.str(m,"eventId");var e=source.get(id);var values=Catalog.allocations(m.get("allocations"));if(e==null||e.type().equals("undo")||allocations.put(id,values)!=null)Purchases.bad("Invalid historical flavour allocation.");for(var a:values)if(!ids.contains(a.productId())||((id.equals(Ledger.OPEN_PURCHASE)||id.equals(Ledger.OPEN_MISSING))&&!a.productId().equals(Catalog.LEGACY)))Purchases.bad("Missing flavour or rewritten opening allocation.");Catalog.forEvent(e,allocations);}
        List<Catalog.Transfer> transfers=new ArrayList<>();Set<String> transferIds=new HashSet<>();for(Object value:Purchases.list(data.get("transfers"))){var t=Catalog.transfer(value);if(t.afterEventId()!=null&&!source.containsKey(t.afterEventId()))Purchases.bad("Transfer anchor is missing.");if(!transferIds.add(t.id())||!ids.contains(t.from())||!ids.contains(t.to()))Purchases.bad("Invalid flavour transfer.");transfers.add(t);}var stock=Catalog.stock(events,allocations,transfers);for(long q:stock.values())if(q<0)Purchases.bad("Negative flavour inventory in backup.");long sum=0;for(long q:stock.values())sum+=q;if(sum!=Ledger.totals(events).stock())Purchases.bad("Catalogue and ledger stock disagree.");
    }
    private CatalogBackup(){}
}

